  "inlineSchema": "// Karvaan POS Core Edition - Enterprise Database Schema\n// Optimized for NestJS + Prisma ORM + SQLite (production-ready, multi-year reliable)\n\ngenerator client {\n  provider = \"prisma-client-js\"\n}\n\ndatasource db {\n  // SQLite: zero-setup, single file, ideal for local restaurant PC deployment\n  // To migrate to PostgreSQL, change provider to \"postgresql\" and set DATABASE_URL\n  provider = \"sqlite\"\n  url      = \"file:./dev.db\"\n}\n\nmodel User {\n  id          String   @id @default(uuid())\n  name        String\n  pin         String   @unique\n  role        String   @default(\"CASHIER\") // ADMIN, MANAGER, CASHIER, WAITER, KITCHEN, DELIVERY\n  phone       String?\n  isActive    Boolean  @default(true)\n  permissions String? // JSON: {\"canVoid\":true,\"canDiscount\":true}\n  createdAt   DateTime @default(now())\n  updatedAt   DateTime @updatedAt\n\n  ordersCreated  Order[]         @relation(\"WaiterOrders\")\n  billsSettled   Bill[]          @relation(\"CashierBills\")\n  deliveryOrders DeliveryOrder[] @relation(\"RiderOrders\")\n}\n\nmodel Table {\n  id             String   @id @default(uuid())\n  tableNumber    String   @unique\n  capacity       Int      @default(4)\n  status         String   @default(\"AVAILABLE\") // AVAILABLE, OCCUPIED, RESERVED, BILLED\n  currentOrderId String?\n  createdAt      DateTime @default(now())\n  updatedAt      DateTime @updatedAt\n\n  orders Order[]\n}\n\nmodel Category {\n  id        String    @id @default(uuid())\n  name      String    @unique\n  sortOrder Int       @default(0)\n  products  Product[]\n}\n\nmodel Product {\n  id              String   @id @default(uuid())\n  name            String\n  description     String?\n  price           Float\n  gstRate         Float    @default(5.0)\n  categoryId      String\n  isAvailable     Boolean  @default(true)\n  prepTimeMinutes Int      @default(12)\n  imageUrl        String?\n  createdAt       DateTime @default(now())\n  updatedAt       DateTime @updatedAt\n\n  category   Category    @relation(fields: [categoryId], references: [id])\n  orderItems OrderItem[]\n}\n\nmodel Customer {\n  id            String   @id @default(uuid())\n  name          String\n  mobile        String   @unique\n  email         String?\n  address       String?\n  totalSpend    Float    @default(0.0)\n  loyaltyPoints Int      @default(0)\n  creditBalance Float    @default(0.0)\n  createdAt     DateTime @default(now())\n  updatedAt     DateTime @updatedAt\n\n  orders        Order[]\n  ledgerEntries LedgerEntry[]\n}\n\nmodel Order {\n  id          String   @id @default(uuid())\n  orderNumber String   @unique\n  orderType   String   @default(\"DINE_IN\") // DINE_IN, PARCEL, DELIVERY\n  tableId     String?\n  waiterId    String?\n  customerId  String?\n  status      String   @default(\"RECEIVED\") // RECEIVED, COOKING, READY, SERVED, CANCELLED\n  totalAmount Float    @default(0.0)\n  discount    Float    @default(0.0)\n  notes       String?\n  createdAt   DateTime @default(now())\n  updatedAt   DateTime @updatedAt\n\n  table    Table?      @relation(fields: [tableId], references: [id])\n  waiter   User?       @relation(\"WaiterOrders\", fields: [waiterId], references: [id])\n  customer Customer?   @relation(fields: [customerId], references: [id])\n  items    OrderItem[]\n  bill     Bill?\n}\n\nmodel OrderItem {\n  id        String   @id @default(uuid())\n  orderId   String\n  productId String\n  quantity  Int      @default(1)\n  price     Float\n  notes     String?\n  addons    String? // JSON: [{name, price}]\n  status    String   @default(\"NEW\") // NEW, SENT, COOKING, READY, SERVED\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  order   Order   @relation(fields: [orderId], references: [id], onDelete: Cascade)\n  product Product @relation(fields: [productId], references: [id])\n}\n\nmodel Bill {\n  id            String   @id @default(uuid())\n  billNumber    String   @unique\n  orderId       String   @unique\n  orderType     String   @default(\"DINE_IN\")\n  subtotal      Float\n  cgst          Float    @default(0.0)\n  sgst          Float    @default(0.0)\n  discount      Float    @default(0.0)\n  deliveryFee   Float    @default(0.0)\n  grandTotal    Float\n  paymentMethod String   @default(\"CASH\") // CASH, CARD, UPI, CREDIT, SPLIT\n  cashierId     String?\n  customerName  String?\n  customerPhone String?\n  waiterName    String?\n  settledAt     DateTime @default(now())\n\n  order   Order @relation(fields: [orderId], references: [id])\n  cashier User? @relation(\"CashierBills\", fields: [cashierId], references: [id])\n}\n\nmodel DeliveryOrder {\n  id              String    @id @default(uuid())\n  orderNumber     String    @unique\n  customerName    String\n  customerPhone   String?\n  deliveryAddress String?\n  deliveryLat     Float?\n  deliveryLng     Float?\n  riderId         String?\n  riderName       String?\n  status          String    @default(\"RECEIVED\") // RECEIVED, PREPARING, READY, OUT_FOR_DELIVERY, DELIVERED, CANCELLED\n  paymentMethod   String    @default(\"CASH\") // CASH, UPI, CARD\n  paymentStatus   String    @default(\"PENDING\") // PENDING, COLLECTED\n  grandTotal      Float     @default(0.0)\n  deliveryFee     Float     @default(0.0)\n  collectedAmount Float?\n  items           String // JSON string of order items\n  notes           String?\n  dispatchedAt    DateTime?\n  deliveredAt     DateTime?\n  createdAt       DateTime  @default(now())\n  updatedAt       DateTime  @updatedAt\n\n  rider User? @relation(\"RiderOrders\", fields: [riderId], references: [id])\n}\n\nmodel ParkedOrder {\n  id        String   @id @default(uuid())\n  orderId   String   @unique // Client-side order ID from frontend\n  data      String // Full JSON snapshot of cart state\n  heldAt    DateTime @default(now())\n  updatedAt DateTime @updatedAt\n}\n\nmodel InventoryItem {\n  id           String   @id @default(uuid())\n  name         String   @unique\n  category     String // e.g. \"Vegetables\", \"Dairy\", \"Meat\", \"Dry Pantry\"\n  currentStock Float    @default(0.0)\n  unit         String   @default(\"kg\")\n  minThreshold Float    @default(5.0)\n  costPrice    Float    @default(0.0)\n  updatedAt    DateTime @updatedAt\n\n  logs StockLog[]\n}\n\nmodel StockLog {\n  id             String   @id @default(uuid())\n  itemId         String\n  type           String // \"IN\", \"OUT\", \"ADJUSTMENT\", \"WASTE\"\n  quantityChange Float\n  reason         String? // \"SALE\", \"DAMAGE\", \"EXPIRY\", \"RETURN\", \"PURCHASE\"\n  orderId        String?\n  notes          String?\n  createdAt      DateTime @default(now())\n\n  item InventoryItem @relation(fields: [itemId], references: [id], onDelete: Cascade)\n}\n\nmodel WasteLog {\n  id         String   @id @default(uuid())\n  itemName   String\n  quantity   Float\n  unit       String   @default(\"pcs\")\n  reason     String // \"RETURN\", \"SPOILAGE\", \"EXPIRY\", \"DAMAGE\"\n  orderId    String?\n  billNumber String?\n  loggedBy   String?\n  createdAt  DateTime @default(now())\n}\n\nmodel LedgerEntry {\n  id           String   @id @default(uuid())\n  customerId   String\n  customerName String\n  amount       Float\n  type         String   @default(\"CREDIT\") // CREDIT, PAYMENT\n  billNumber   String?\n  notes        String?\n  createdAt    DateTime @default(now())\n\n  customer Customer @relation(fields: [customerId], references: [id])\n}\n\nmodel ReturnRecord {\n  id           String   @id @default(uuid())\n  billNumber   String\n  orderType    String\n  reason       String\n  action       String // \"RESTOCK\", \"WASTE\"\n  refundDest   String // \"CASH\", \"UPI\", \"LEDGER\"\n  totalRefund  Float\n  items        String // JSON string of returned items\n  authorizedBy String?\n  createdAt    DateTime @default(now())\n}\n\nmodel BackupLog {\n  id        String   @id @default(uuid())\n  filename  String\n  sizeBytes Int?\n  status    String   @default(\"SUCCESS\") // SUCCESS, FAILED\n  error     String?\n  createdAt DateTime @default(now())\n}\n",
